func TestLoadPreviousReports(t *testing.T) {
	requireTestdata(t, "testdata/report.json")
	out := t.TempDir()
	jsonDir := filepath.Join(out, jsonSubdir)
	if err := os.MkdirAll(jsonDir, 0o755); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile("testdata/report.json")
	if err != nil {
		t.Fatal(err)
	}
	for name, content := range map[string][]byte{
		"old_111111.json":     data,
		"current_222222.json": data,
		"broken_333333.json":  []byte("{not json"),
		hashCacheFile:         []byte(`{"/x.tar":{"Size":1,"ModTime":"2026-01-01T00:00:00Z","Hash":"abcdef"}}`),
	} {
		if err := os.WriteFile(filepath.Join(jsonDir, name), content, 0o644); err != nil {
			t.Fatal(err)
		}
	}

	rows := map[string]summaryRow{}
	loadPreviousReports(out, []scanTarget{{Stem: "current_222222"}}, nil, rows)

	if row, ok := rows["old_111111"]; !ok || len(rows) != 1 || row.Status != statusPrevious {
		t.Fatalf("rows = %v, want only old_111111 marked previous (current is rescanned, broken and .hashes.json are skipped)", rows)
	}
	if _, err := os.Stat(filepath.Join(out, htmlSubdir, "old_111111.html")); err != nil {
		t.Errorf("detail page for previous report not rendered: %v", err)
	}
}

func TestReportStem(t *testing.T) {
	dir := t.TempDir()
	tar := filepath.Join(dir, "My.Image.TAR.GZ")
	if err := os.WriteFile(tar, []byte("content"), 0o644); err != nil {
		t.Fatal(err)
	}
	// sha256("content") = ed7002...
	h, err := fileHash(context.Background(), tar)
	if err != nil {
		t.Fatal(err)
	}
	if got := reportStem(tar, h); got != "My.Image_ed7002" {
		t.Errorf("reportStem(tar) = %q", got)
	}
	if got := reportStem("registry.io/app:1.0", ""); !strings.HasPrefix(got, "app_1.0_") {
		t.Errorf("reportStem(image ref) = %q", got)
	}
}

func TestIsReportFresh(t *testing.T) {
	path := filepath.Join(t.TempDir(), "r.json")
	if isReportFresh(path, time.Time{}) {
		t.Error("missing file reported fresh")
	}
	if err := os.WriteFile(path, []byte("{}"), 0o644); err != nil {
		t.Fatal(err)
	}
	if !isReportFresh(path, time.Now().Add(-time.Hour)) {
		t.Error("report newer than DB should be fresh")
	}
	if isReportFresh(path, time.Now().Add(time.Hour)) {
		t.Error("report older than DB should be stale")
	}
}

func TestErrorClassification(t *testing.T) {
	out := "2026-11-14T14:38:13+07:00\tFATAL\tFatal error\trun error: context deadline exceeded"
	if msg := trivyErrorMessage(out); !strings.HasPrefix(msg, "FATAL") {
		t.Errorf("trivyErrorMessage = %q", msg)
	}
	timeout := fmt.Errorf("%w after 10m: %s", errScanTimeout, trivyErrorMessage(out))
	if isRetryableError(timeout) {
		t.Error("scan timeout must not be retried")
	}
	if !isRetryableError(errors.New("trivy failed: database is locked")) {
		t.Error("locked DB should be retried")
	}
	if isRetryableError(errors.New("unable to initialize archive image: connection")) {
		t.Error("invalid image must not be retried")
	}
	// Real trivy output for a missing tag / missing repository.
	for _, msg := range []string{
		`remote error: GET https://index.docker.io/v2/library/alpine/manifests/no-such-tag: MANIFEST_UNKNOWN: manifest unknown`,
		`remote error: GET https://index.docker.io/v2/library/nope/manifests/latest: UNAUTHORIZED: authentication required`,
	} {
		if isRetryableError(errors.New("trivy failed: exit status 1: " + msg + " connection i/o timeout")) {
			t.Errorf("registry rejection must not be retried: %s", msg)
		}
	}
}

func TestIsDockerDigestError(t *testing.T) {
	real := errors.New(`trivy failed: exit status 1: FATAL Fatal error run error: image scan error: ` +
		`unable to export the image: Error response from daemon: unable to create manifests file: ` +
		`NotFound: content digest sha256:6cbaee6f841f2230bcf06a4d2c52d00aef82fd36db93b70ca54cc980470736b3: not found`)
	if !isDockerDigestError(real) {
		t.Error("daemon digest error not recognised")
	}
	if isRetryableError(real) {
		t.Error("daemon digest error must not be retried")
	}
	for _, msg := range []string{
		`trivy failed: MANIFEST_UNKNOWN: manifest unknown`,
		`trivy failed: connection reset by peer`,
	} {
		if isDockerDigestError(errors.New(msg)) {
			t.Errorf("not a daemon digest error: %s", msg)
		}
	}
}

func TestScanExitCode(t *testing.T) {
	success := []scanResult{
		{Target: scanTarget{Input: "a", Stem: "a_1"}},
		{Target: scanTarget{Input: "b", Stem: "b_1"}},
	}
	rows := map[string]summaryRow{
		"a_1": {Stem: "a_1", Worst: "CRITICAL"},
		"b_1": {Stem: "b_1", Worst: "LOW"},
	}
	tests := []struct {
		name          string
		failOn        string
		failed        []scanResult
		summaryFailed bool
		want          int
	}{
		{"clean", "", nil, false, 0},
		{"threshold hit", "HIGH", nil, false, 2},
		{"summary failure wins over threshold", "HIGH", nil, true, 1},
		{"scan failure", "", []scanResult{{}}, false, 1},
		{"summary failure", "", nil, true, 1},
	}
	for _, tt := range tests {
		if got := scanExitCode(tt.failOn, success, tt.failed, rows, tt.summaryFailed); got != tt.want {
			t.Errorf("%s: scanExitCode = %d, want %d", tt.name, got, tt.want)
		}
	}
}

